/// <summary>
/// Class is used to get record from table <c>EcoResProductServiceWarranty</c> based on pricingObject parameter.
/// </summary>
internal abstract class GUPPricingAttributeEcoResProductServiceWarranty extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected EcoResProductServiceWarranty getTableRecord(Common _pricingObject)
    {
        SalesLine                       salesLine;
        SalesQuotationLine              salesQoutationLine;
        EcoResProduct                   product;
        EcoResDistinctProduct           distinctProduct;
        EcoResProductServiceWarranty    warrantyProduct;

        Switch (_pricingObject.tableId)
        {

            case tableNum(SalesLine):
                salesLine = _pricingObject as SalesLine;
                if (salesLine)
                {
                    product = salesLine.inventTable().Product();
                }
                break;

            case tableNum(SalesQuotationLine):
                salesQoutationLine = _pricingObject as SalesQuotationLine;
                if (salesQoutationLine)
                {
                    product = salesQoutationLine.inventTable().Product();
                }
                break;
        }

        if (product)
        {
            distinctProduct = EcoResDistinctProduct::find(product.RecId);

            if (distinctProduct)
            {
                select firstonly warrantyProduct
                    where warrantyProduct.DistinctProduct == distinctProduct.RecId;
            }
        }

        return warrantyProduct;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(EcoResProductServiceWarranty)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(EcoResProductServiceWarranty));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(EcoResProductServiceWarranty));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(EcoResProductServiceWarranty), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
